const $=id=>document.getElementById(id);
const species=[{id:'frog',name:'Red-eyed tree frog',latin:'Agalychnis callidryas',category:'AMPHIBIAN · HYLIDAE',title:'Small wonder.<br>Wild color.',description:'Meet the red-eyed tree frog. A tiny resident of the canopy with a remarkably vivid presence.',detail:'A nocturnal tree-dweller from Central America. Its brilliant red eyes and orange toes make a striking contrast with its leaf-green body. Adhesive toe pads help it move effortlessly through the foliage.',habitat:'Canopy & understory',range:'Central America',diet:'Insects',size:'4–7 cm',status:'Least concern',region:'central'}, {id:'toucan',name:'Keel-billed toucan',latin:'Ramphastos sulfuratus',category:'BIRD · RAMPHASTIDAE',title:'A splash of color.<br>A song of the forest.',description:'A bright beak, a curious gaze, and a life among the treetops. Meet one of the forest’s most recognizable residents.',detail:'The keel-billed toucan lives in tropical forests from southern Mexico to northern South America. Its large, lightweight bill helps it reach fruit. By dispersing seeds, toucans help shape the forest around them.',habitat:'Canopy',range:'Central & South America',diet:'Mostly fruit',size:'42–55 cm',status:'Near threatened',region:'central'},{id:'jaguar',name:'Jaguar',latin:'Panthera onca',category:'MAMMAL · FELIDAE',title:'Quiet steps.<br>Powerful presence.',description:'Follow the forest’s elusive big cat. A powerful swimmer and a vital part of the rainforest ecosystem.',detail:'The jaguar is the largest wild cat in the Americas. Its rosette-patterned coat blends into dappled forest light. Unlike many cats, jaguars readily swim and hunt around rivers and wetlands.',habitat:'Forest floor',range:'Central & South America',diet:'Carnivore',size:'1.1–1.8 m body length',status:'Near threatened',region:'amazon'}];
let selected=0,view='overview',paused=matchMedia('(prefers-reduced-motion: reduce)').matches,saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('canopy-saved')||'[]'))}catch{}
const mat=(color,roughness=.6)=>new T.MeshStandardMaterial({color,roughness});
function ell(parent,m,p,s){const x=new T.Mesh(new T.SphereGeometry(1,40,24),m);x.position.set(...p);x.scale.set(...s);parent.add(x);return x}
function line(parent,m,a,b,r){const va=new T.Vector3(...a),vb=new T.Vector3(...b),mesh=new T.Mesh(new T.CylinderGeometry(r,r,va.distanceTo(vb),14),m);mesh.position.copy(va.clone().add(vb).multiplyScalar(.5));mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),vb.sub(va).normalize());parent.add(mesh);ell(parent,m,a,[r,r,r]);ell(parent,m,b,[r,r,r]);return mesh}
function leaf(parent,pos,scale=1,rot=0){const g=new T.Group();g.position.set(...pos);g.rotation.z=rot;const mesh=ell(g,mat('#628d3d'),[0,.35,0],[.29,.7,.055]);mesh.rotation.z=-.3;line(g,mat('#91b45d'),[0,-.25,.055],[-.18,.85,.055],.011);for(let i=0;i<5;i++){const y=i*.18;line(g,mat('#7f9e50'),[-y*.2,y,.057],[-.24-y*.05,y+.2,.057],.004);line(g,mat('#7f9e50'),[-y*.2,y,.057],[.18-y*.15,y+.12,.057],.004)}g.scale.setScalar(scale);parent.add(g)}
function branch(parent){const m=mat('#675b3e');line(parent,m,[-2.1,-.8,.35],[2.2,-1,.1],.16);line(parent,m,[.7,-.95,.2],[1.8,-.42,.05],.065);leaf(parent,[1.65,-.47,.07],.8,-.6);leaf(parent,[-1.8,-.74,.18],1.1,.6);leaf(parent,[-1.7,-.78,.16],.7,-.65);for(let i=0;i<11;i++)ell(parent,mat('#779056'),[-1.7+i*.31,-.65-i*.014,.37],[.10,.028,.055])}
function frog(){const g=new T.Group(),green=mat('#77ba35',.35),lime=mat('#9cd651',.4),blue=mat('#257998'),orange=mat('#ec7523',.35),red=mat('#e33d21',.3),black=mat('#111c16',.25);branch(g);const animal=new T.Group();g.add(animal);ell(animal,green,[0,-.03,0],[.71,.54,.66]);ell(animal,lime,[0,-.21,.37],[.53,.34,.40]);ell(animal,green,[0,.34,.42],[.78,.47,.5]);ell(animal,lime,[0,.18,.75],[.63,.19,.17]);for(const sign of [-1,1]){ell(animal,green,[sign*.47,.69,.62],[.30,.33,.26]);ell(animal,orange,[sign*.47,.69,.823],[.224,.236,.07]);ell(animal,red,[sign*.47,.70,.86],[.189,.20,.055]);ell(animal,black,[sign*.47,.70,.906],[.04,.16,.022]);ell(animal,mat('#fff6d9'),[sign*.42,.79,.926],[.027,.03,.01]);ell(animal,black,[sign*.21,.38,.885],[.026,.018,.012]);ell(animal,blue,[sign*.62,-.10,.11],[.12,.29,.4]);for(let i=0;i<4;i++)line(animal,lime,[sign*.65,-.32+i*.14,.12],[sign*.66,-.32+i*.14,.35],.033);line(animal,green,[sign*.53,.03,.51],[sign*.90,-.38,.67],.085);line(animal,lime,[sign*.90,-.38,.67],[sign*.83,-.67,.69],.065);for(let i=0;i<3;i++){line(animal,orange,[sign*.83,-.63,.7],[sign*(.73+i*.12),-.78,.83+i*.04],.025);ell(animal,orange,[sign*(.73+i*.12),-.78,.83+i*.04],[.064,.028,.064])}ell(animal,green,[sign*.65,-.22,-.27],[.36,.30,.32]);line(animal,lime,[sign*.86,-.25,-.26],[sign*1.22,-.51,.12],.08);line(animal,green,[sign*1.22,-.51,.12],[sign*1.03,-.75,.29],.075);for(let i=0;i<3;i++){line(animal,orange,[sign*1.02,-.73,.28],[sign*(1+i*.13),-.85,.40+i*.05],.032);ell(animal,orange,[sign*(1+i*.13),-.85,.40+i*.05],[.072,.03,.07])}}const curve=new T.CatmullRomCurve3([new T.Vector3(-.5,.15,.868),new T.Vector3(0,.11,.914),new T.Vector3(.5,.15,.868)]);animal.add(new T.Mesh(new T.TubeGeometry(curve,24,.009,5,false),mat('#3f692c')));g.userData.body=animal;return g}
function toucan(){const g=new T.Group();branch(g);const body=new T.Group();g.add(body);const black=mat('#202a29'),yellow=mat('#f5c74f'),orange=mat('#ed823a'),green=mat('#a4bf45');ell(body,black,[0,-.03,0],[.47,.76,.4]);ell(body,black,[-.14,.59,.1],[.42,.43,.37]);ell(body,yellow,[.02,.18,.34],[.34,.52,.115]);ell(body,black,[-.35,-.12,.02],[.23,.59,.37]);ell(body,mat('#39413b'),[-.49,-.16,.12],[.055,.48,.22]);const tail=ell(body,black,[-.20,-.69,-.22],[.22,.58,.13]);tail.rotation.x=-.5;ell(body,green,[.49,.6,.13],[.62,.24,.26]);ell(body,orange,[.60,.50,.25],[.5,.10,.18]);ell(body,mat('#e5a73d'),[.53,.73,.18],[.45,.12,.19]);ell(body,mat('#b74237'),[.95,.6,.15],[.20,.19,.22]);ell(body,mat('#4b9ba0'),[.02,.73,.414],[.13,.13,.035]);ell(body,mat('#111914'),[.02,.73,.441],[.075,.081,.019]);ell(body,mat('#fffbd4'),[.0,.758,.46],[.023,.023,.01]);for(const s of [-1,1]){line(body,mat('#687f85'),[s*.17,-.57,.09],[s*.2,-.84,.24],.042);for(let j=0;j<3;j++)line(body,mat('#687f85'),[s*.2,-.83,.23],[s*.2+(j-1)*.09,-.89,.46],.023)}g.userData.body=body;return g}
function jaguar(){const g=new T.Group(),body=new T.Group();g.add(body);const fur=mat('#d5a74c'),cream=mat('#efdbad'),black=mat('#352d20');const floor=ell(g,mat('#6b8050'),[0,-1.06,0],[1.8,.1,1]);leaf(g,[-1.6,-1,.1],.75,.5);leaf(g,[1.55,-1,-.1],.65,-.8);ell(body,fur,[-.16,-.13,-.1],[.99,.46,.40]);ell(body,fur,[.8,.12,.17],[.40,.41,.36]);ell(body,cream,[.95,-.03,.43],[.31,.19,.16]);ell(body,black,[.95,.03,.565],[.085,.05,.045]);for(const s of [-1,1]){ell(body,fur,[.81+s*.24,.46,.14],[.15,.19,.09]);ell(body,black,[.81+s*.24,.48,.211],[.084,.1,.018]);ell(body,mat('#a2b66b'),[.79+s*.19,.22,.458],[.073,.052,.024]);ell(body,black,[.79+s*.19,.22,.478],[.016,.043,.013]);for(const x of [-.73,.50]){line(body,fur,[x,-.35,s*.24],[x+.04,-.85,s*.26],.12);ell(body,fur,[x+.1,-.88,s*.27],[.20,.12,.16])}}const curve=new T.CatmullRomCurve3([new T.Vector3(-1,-.2,-.1),new T.Vector3(-1.4,-.10,-.2),new T.Vector3(-1.5,.25,-.25),new T.Vector3(-1.3,.42,-.22)]);body.add(new T.Mesh(new T.TubeGeometry(curve,30,.06,9,false),fur));for(let i=0;i<32;i++){const x=-.94+(i%8)*.23,y=-.40+Math.floor(i/8)*.17,z=.29+Math.sin(i)*.045;const spot=new T.Mesh(new T.TorusGeometry(.045,.015,5,8),black);spot.position.set(x,y,z);spot.scale.set(1.15,.85,1);body.add(spot)}for(let i=0;i<10;i++)ell(body,black,[.53+(i%4)*.17,.1+Math.floor(i/4)*.1,.40],[.022,.021,.01]);g.userData.body=body;g.rotation.y=-.25;return g}
const factories=[frog,toucan,jaguar];let mainScene,thumbs=[];
function setup(canvas,index,thumbnail=false){const renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;const scene=new T.Scene(),camera=new T.PerspectiveCamera(33,1,.1,100);camera.position.set(0,.55,thumbnail?7.5:6.9);camera.lookAt(0,-.08,0);scene.add(new T.HemisphereLight('#fff4d7','#24442e',2.6));const key=new T.DirectionalLight('#ffefd0',4);key.position.set(-3,5,5);scene.add(key);const rim=new T.DirectionalLight('#bddc99',2);rim.position.set(3,3,-3);scene.add(rim);let model=factories[index]();scene.add(model);model.rotation.y=thumbnail?-.2:-.30;const resize=()=>{const box=canvas.parentElement.getBoundingClientRect();renderer.setSize(box.width,box.height,false);camera.aspect=box.width/box.height;camera.updateProjectionMatrix();renderer.render(scene,camera)};const obs=new ResizeObserver(resize);obs.observe(canvas.parentElement);resize();return{renderer,scene,camera,model,obs,set(i){scene.remove(this.model);this.model.traverse(o=>{o.geometry?.dispose();if(o.material) o.material.dispose()});this.model=factories[i]();this.model.rotation.y=-.3;scene.add(this.model)},draw(time){if(!paused&&!thumbnail){this.model.userData.body.position.y=Math.sin(time*.0015)*.035}renderer.render(scene,camera)}}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2700)}
function persist(){try{localStorage.setItem('canopy-saved',JSON.stringify([...saved]))}catch{}updateSaved()}
function updateSaved(){const is=saved.has(species[selected].id);$('save').textContent=is?'♥':'♡';$('save').setAttribute('aria-pressed',is);$('save').setAttribute('aria-label',is?'Remove species from collection':'Save species');$('saved-count').textContent=saved.size;$('collection-metric').innerHTML=`${saved.size} <em>saved discoveries</em>`;$('detail-save').textContent=is?'Remove from collection ♥':'Save to collection ♡'}
function toggleSave(){const s=species[selected];if(saved.has(s.id)){saved.delete(s.id);toast('Removed from your collection')}else{saved.add(s.id);toast(`${s.name} saved to your collection`)}persist();if(view==='saved')renderCards()}
function renderCards(){thumbs.forEach(t=>{t.obs.disconnect();t.renderer.dispose();t.model.traverse(o=>{o.geometry?.dispose();o.material?.dispose()})});thumbs=[];const list=species.map((s,i)=>({s,i})).filter(({s})=>view!=='saved'||saved.has(s.id));$('animal-grid').innerHTML=list.map(({s,i})=>`<article class="animal-card ${i===selected?'selected':''}"><div class="animal-art"><canvas aria-label="3D ${s.name}"></canvas></div><div class="animal-info"><span class="tiny">${s.category.split(' · ')[0]}</span><h4>${s.name}</h4><i>${s.latin}</i><span class="status">${s.status}</span><span class="card-arrow">↗</span></div><button aria-label="View ${s.name}" data-species="${i}"></button></article>`).join('');$('empty').hidden=!!list.length;document.querySelectorAll('[data-species]').forEach(b=>b.onclick=()=>selectSpecies(Number(b.dataset.species)));document.querySelectorAll('.animal-art canvas').forEach((c,i)=>{try{const t=setup(c,list[i].i,true);thumbs.push(t)}catch{c.parentElement.textContent=list[i].s.name}})}
function selectSpecies(i){selected=i;const s=species[i];$('animal-class').textContent=s.category;$('animal-name').innerHTML=s.title;$('animal-description').textContent=s.description;document.querySelector('.edition').textContent=`0${i+1} / 03`;$('scene').setAttribute('aria-label',`Interactive 3D ${s.name}. Drag to rotate. Arrow keys rotate, plus and minus zoom.`);mainScene?.set(i);updateSaved();document.querySelectorAll('.animal-card').forEach(c=>c.classList.toggle('selected',Number(c.querySelector('button').dataset.species)===i))}
function setView(v){view=v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));const labels={overview:'Overview',species:'Wildlife atlas',habitats:'Habitats',saved:'My collection'};$('view-label').textContent=labels[v];$('page-title').textContent={overview:'A world worth exploring.',species:'Life, in extraordinary detail.',habitats:'Many layers. One living forest.',saved:'Your own corner of the wild.'}[v];$('species-heading').textContent=v==='saved'?'Your saved discoveries':'Meet the forest residents';renderCards();if(v==='habitats')document.querySelector('.layers').scrollIntoView({behavior:paused?'instant':'smooth',block:'center'})}
$('save').onclick=toggleSave;$('detail-save').onclick=toggleSave;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('view-all').onclick=()=>setView('species');$('explore').onclick=()=>{const s=species[selected];$('detail-title').textContent=s.name;$('detail-category').textContent=s.category;$('detail-latin').textContent=s.latin;$('detail-description').textContent=s.detail;$('detail-facts').innerHTML=[['Habitat',s.habitat],['Range',s.range],['Diet',s.diet],['Size',s.size]].map(([k,v])=>`<div><span>${k}</span>${v}</div>`).join('');updateSaved();$('detail').showModal()};document.querySelector('.dialog-close').onclick=()=>$('detail').close();$('detail').onclick=e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close()}};
$('info').onclick=()=>toast('Canopy is an educational demo with stylized 3D wildlife and curated species notes.');$('region').onchange=()=>{const i=$('region').value==='amazon'?2:0;selectSpecies(i);toast($('region').selectedOptions[0].textContent+' spotlight selected')};
const layerText={emergent:'The tallest trees rise above the forest roof. Sunlight and strong winds shape life at this height.',canopy:'The leafy roof of the forest. Home to tree frogs, toucans, and an astonishing variety of life.',understory:'A sheltered world of soft light. Broad leaves capture the sunlight filtering through the canopy.',floor:'The forest’s foundation. Fungi recycle fallen leaves, and jaguars move through the shadows.'};document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('selected',x===b));$('layer-description').textContent=layerText[b.dataset.layer];if(b.dataset.layer==='floor')selectSpecies(2);if(b.dataset.layer==='canopy')selectSpecies(1);if(b.dataset.layer==='understory')selectSpecies(0)});
try{mainScene=setup($('scene'),0);let dragging=false,lastX=0,lastY=0;$('scene').onpointerdown=e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;$('scene').setPointerCapture(e.pointerId)};$('scene').onpointermove=e=>{if(!dragging)return;mainScene.model.rotation.y+=(e.clientX-lastX)*.008;mainScene.model.rotation.x=T.MathUtils.clamp(mainScene.model.rotation.x+(e.clientY-lastY)*.004,-.45,.45);lastX=e.clientX;lastY=e.clientY};$('scene').onpointerup=$('scene').onpointercancel=()=>dragging=false;const zoom=d=>mainScene.camera.position.z=T.MathUtils.clamp(mainScene.camera.position.z+d,4.5,10);$('zoom-in').onclick=()=>zoom(-.6);$('zoom-out').onclick=()=>zoom(.6);$('reset').onclick=()=>{mainScene.model.rotation.set(0,-.3,0);mainScene.camera.position.z=6.9};$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▷':'Ⅱ';$('pause').setAttribute('aria-pressed',paused);$('pause').setAttribute('aria-label',paused?'Resume animal animation':'Pause animal animation')};$('scene').onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')mainScene.model.rotation.y-=.15;if(e.key==='ArrowRight')mainScene.model.rotation.y+=.15;if(e.key==='ArrowUp')mainScene.model.rotation.x=Math.max(-.45,mainScene.model.rotation.x-.1);if(e.key==='ArrowDown')mainScene.model.rotation.x=Math.min(.45,mainScene.model.rotation.x+.1);if(e.key==='+')zoom(-.6);if(e.key==='-')zoom(.6)};function tick(t){mainScene.draw(t);thumbs.forEach(x=>x.draw(t));requestAnimationFrame(tick)}requestAnimationFrame(tick)}catch(error){$('render-error').hidden=false;console.warn('WebGL unavailable',error)}
renderCards();updateSaved();$('pause').setAttribute('aria-pressed',paused);$('pause').textContent=paused?'▷':'Ⅱ';
